func cmdCheckpoints(args []string) {
	if len(args) < 1 {
		fmt.Fprintf(os.Stderr, "usage: mlpipe checkpoints <model>\n")
		os.Exit(1)
	}
	model := args[0]

	entry, err := resolveModel(model)
	if err != nil {
		fmt.Fprintf(os.Stderr, "not found\n")
		os.Exit(1)
	}

	entries, err := os.ReadDir(checkpointsDir(entry.Path))
	if err != nil || len(entries) == 0 {
		fmt.Println("no checkpoints")
		return
	}

	type checkpointInfo struct {
		name string
		mod  time.Time
	}
	var cps []checkpointInfo
	for _, entry := range entries {
		if !entry.IsDir() {
			continue
		}
		info, err := entry.Info()
		if err != nil {
			continue
		}
		cps = append(cps, checkpointInfo{name: entry.Name(), mod: info.ModTime()})
	}

	if len(cps) == 0 {
		fmt.Println("no checkpoints")
		return
	}

	sort.Slice(cps, func(i, j int) bool {
		return cps[i].mod.Before(cps[j].mod)
	})

	for _, cp := range cps {
		fmt.Printf("%s  %s\n", cp.name, cp.mod.Format("2006-01-02 15:04:05"))
	}
}

